import app from 'flarum/admin/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import ConnectionTest, { ConnectionTestState } from './ConnectionTest';
/**
 * Tests a saved connection from the list on the Connections tab.
 */
export default class ConnectionTestModal extends Modal {
  test = (() => new ConnectionTestState())();
  oninit(vnode) {
    super.oninit(vnode);
    this.test.start(this.attrs.name);
  }
  className() {
    return 'AiConnectionTestModal Modal--small';
  }
  title() {
    return app.translator.trans('flarum-ai.admin.test.title', {
      name: this.attrs.name
    });
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m(ConnectionTest, {
      state: this.test
    }), m("div", {
      className: "Form-group Form-controls"
    }, m(Button, {
      className: "Button",
      icon: "fas fa-rotate",
      disabled: this.test.status === 'running',
      onclick: () => this.test.start(this.attrs.name)
    }, app.translator.trans('flarum-ai.admin.test.again_button'))));
  }
}
flarum.reg.add('flarum-ai', 'admin/components/ConnectionTestModal', ConnectionTestModal);